package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edited values; a claim dated inside a closed period, or moved into one, is refused. */
public class ApplyClaim {
    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
            Out<Claim> changed) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
        if (periods.closedOn(claim.sheetId(), claim.date()) || periods.closedOn(claim.sheetId(), date)) {
            throw new InvalidClaimException("The claim's date is inside a closed period");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED, DRAFT or OPEN to VOID. Voiding clears the
 * claim's number; the number it had is kept for the audit line. Settling fixes the claim's due: its amount at its
 * person's grade's rate in force on the claim's date, rounded half to even to two decimals (left live when no rate applies),
 * or the figure a statement bound it to.
 * Opening records who opened the claim; that user cannot settle it (four eyes). A claim dated inside a closed
 * period cannot change status.
 */
public class ApplyClaimStatus {
    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
            PeriodRepository periods, Out<Claim> changed, Out<ClaimNumber> number) throws InvalidClaimStatusException {
        boolean allowed = switch (change.to()) {
            case OPEN -> claim.status() == ClaimStatus.DRAFT;
            case SETTLED -> claim.status() == ClaimStatus.OPEN;
            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        if (change.to() == ClaimStatus.SETTLED && change.by().equals(claim.openedBy())) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it");
        }
        number.set(new ClaimNumber(claim.number()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), change.to(), change.to() == ClaimStatus.VOID ? null : claim.number(),
                change.to() == ClaimStatus.SETTLED ? due(claim, people, rates) : claim.due(),
                change.to() == ClaimStatus.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue()));
    }

    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : ClaimDue.live(claim, person.grade(), rates);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the action is open, settle or void. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> change)
            throws InvalidClaimStatusException {
        String action = request == null || request.action() == null ? "" : request.action().trim();
        ClaimStatus to = switch (action) {
            case "open" -> ClaimStatus.OPEN;
            case "settle" -> ClaimStatus.SETTLED;
            case "void" -> ClaimStatus.VOID;
            default -> throw new InvalidClaimStatusException("The action must be open, settle or void");
        };
        change.set(new ClaimStatusChange(to, request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_OPENED, CLAIM_SETTLED or CLAIM_VOIDED to the audit file once the status is stored, ending
 * with number=<number> when the claim has (or, voided, had) one; CLAIM_SETTLED then ends with the due it fixed
 * (due=n/a when its grade had no rate). Then writes the
 * figures the change moved (see Rollup). */
public class RecordClaimStatusChanged {
    public void record(@Val Claim claim, @Val ClaimStatusChange change, @Val ClaimNumber number,
            PersonRepository people, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String event = switch (claim.status()) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record(event + " sheet=" + claim.sheetId() + " by=" + change.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (number.value() == null ? "" : " number=" + number.value())
                + (claim.status() == ClaimStatus.SETTLED
                        ? " due=" + (claim.due() == null ? "n/a" : claim.due().toPlainString()) : ""));
        rollup.record(claim.sheetId(), change.by(), before);
    }
